import { DEMO_BODIES, DEMO_GENESIS } from './chain-demo-bodies';
import type { DemoScenario } from './chain-demo-bodies';
import { buildChain } from './chain-demo-core';

/** The exact text of chain-demo-data.ts. */
export function chainDemoSource(): string {
  const data: Record<string, unknown> = {};
  for (const id of Object.keys(DEMO_BODIES) as DemoScenario[]) data[id] = buildChain(DEMO_BODIES[id], DEMO_GENESIS);
  return [
    '// GENERATED by scripts/gen-chain-demo.ts from chain-demo-bodies.ts. Do not edit by hand.',
    "import type { ChainedShieldEvent, HeadRecord } from '@exorcist-98/shield/chain-core';",
    "import type { DemoScenario } from './chain-demo-bodies';",
    '',
    'export const CHAIN_DEMO: Record<DemoScenario, { events: ChainedShieldEvent[]; head: HeadRecord }> = ' + JSON.stringify(data, null, 2) + ';',
    '',
  ].join('\n');
}
